            { speaker: 'You', line: '(Pause. You have an idea.)' }
          ],
          choices: [
            { option: 'Could the self-advocacy goal be specific? Like, "I will email a teacher when I am stuck"?', value: 'best', why: 'Specific. Action-oriented. Measurable.' },
